// QueryArrow -
// Query the datacatalog, returning data in Apache Arrow IPC Stream format
func QueryArrow(ctx api.RequestContext, query *query.Query) ([]arrow.Record, error) {
	path := "/v1/api/ulv2/datacatalog/query"

	params := [][2]string{}

	headers := map[string]string{}
	headers["accept"] = "application/vnd.apache.arrow.stream"

	bodyBytes := query.ToBytes()
	res, err := ctx.Post(path, bodyBytes, "application/octet-stream", params, headers)
	if err != nil {
		return nil, err
	}
	records, err := api.ReadArrowIPC(res)
	if err != nil {
		return nil, fmt.Errorf("failed to deserialize Arrow IPC response: %w", err)
	}
	return records, nil
}

